using Store;

namespace ShoppingCart.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private Store.ShoppingCart _cart;

    [TestInitialize]
    public void Setup()
    {
        _cart = new Store.ShoppingCart();
    }

    // --- AddItem ---

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _cart.AddItem("SKU-001", 2, 9.99m);

        var total = _cart.CalculateTotal();

        Assert.AreEqual(19.98m, total);
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_SumsCorrectly()
    {
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.AddItem("SKU-002", 3, 5.00m);

        var total = _cart.CalculateTotal();

        Assert.AreEqual(25.00m, total);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_AccumulatesQuantity()
    {
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.AddItem("SKU-001", 2, 10.00m);

        var total = _cart.CalculateTotal();

        Assert.AreEqual(30.00m, total);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQuantity_ThrowsArgumentException(int quantity)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem("SKU-001", quantity, 5.00m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-0.01)]
    public void AddItem_InvalidPrice_ThrowsArgumentException(double price)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem("SKU-001", 1, (decimal)price));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void AddItem_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(sku!, 1, 5.00m));
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.AddItem("SKU-002", 1, 5.00m);

        _cart.RemoveItem("SKU-001");

        var total = _cart.CalculateTotal();
        Assert.AreEqual(5.00m, total);
    }

    [TestMethod]
    public void RemoveItem_OnlyItem_CartTotalIsZero()
    {
        _cart.AddItem("SKU-001", 1, 15.00m);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsInvalidOperationException()
    {
        Assert.ThrowsExactly<InvalidOperationException>(() => _cart.RemoveItem("MISSING"));
    }

    // --- CalculateTotal ---

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        var total = _cart.CalculateTotal();

        Assert.AreEqual(0m, total);
    }

    [TestMethod]
    public void CalculateTotal_AfterAddAndRemove_ReflectsRemainingItems()
    {
        _cart.AddItem("SKU-001", 1, 20.00m);
        _cart.AddItem("SKU-002", 2, 7.50m);
        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(15.00m, _cart.CalculateTotal());
    }

    // --- ApplyCoupon ---

    [TestMethod]
    public void ApplyCoupon_ValidCode_ReducesTotal()
    {
        _cart.AddItem("SKU-001", 1, 100.00m);

        _cart.ApplyCoupon("SAVE10");

        Assert.IsGreaterThan(100.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_PercentageDiscount_AppliesCorrectly()
    {
        _cart.AddItem("SKU-001", 2, 50.00m);

        _cart.ApplyCoupon("SAVE10"); // assume 10% off

        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException()
    {
        _cart.AddItem("SKU-001", 1, 50.00m);

        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon("INVALID"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void ApplyCoupon_NullOrEmptyCode_ThrowsArgumentException(string? code)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_EmptyCart_ThrowsInvalidOperationException()
    {
        Assert.ThrowsExactly<InvalidOperationException>(() => _cart.ApplyCoupon("SAVE10"));
    }

    [TestMethod]
    public void ApplyCoupon_AppliedTwice_ThrowsInvalidOperationException()
    {
        _cart.AddItem("SKU-001", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");

        Assert.ThrowsExactly<InvalidOperationException>(() => _cart.ApplyCoupon("SAVE10"));
    }
}

